#!/usr/bin/env node
/**
 * Generated by devkit. Do not edit: run `devkit-init` to update it, and set this app's values in
 * the `deploy` block of `devkit.config.mjs`.
 *
 * Deploys the current commit to production over SSH with Docker Compose (SCRIPT-10, CTR-11).
 * Nothing here imports devkit: a deploy must not depend on development tooling at run time.
 *
 * Before anything reaches the server it refuses a missing target, a dirty tree, and a HEAD that
 * is not a freshly fetched `origin/main`, then runs `npm run validate`. On the server, in order:
 * refuse tracked changes; dump the database and verify the dump; fast-forward the checkout and
 * confirm it is the commit validated here; `docker compose up --build -d --wait`, stopping with
 * the logs if a service is not healthy; install the nginx site file if it changed, testing it and
 * restoring the previous one on failure; prune dangling images.
 *
 * Run with `npm run deploy:prod`, which loads `.env` when it exists. The target comes from the
 * environment: DEPLOY_SSH_HOST, DEPLOY_SSH_PORT (unset: ssh config decides), DEPLOY_REPO_PATH, DEPLOY_BACKUP_DIR
 * (.backups in the server checkout), DEPLOY_NGINX_SITES_DIR (required when a site file is
 * deployed, for example /srv/nginx/sites) and DEPLOY_NGINX_CONTAINER (nginx). Options: --skip-validate, --skip-backup (or DEPLOY_BACKUP=0)
 * when a dump exists another way, --no-prune (or DEPLOY_PRUNE=0), --dry-run, --help.
 */
import { spawnSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

/** Production is always the remote's main (SCRIPT-10); there is no branch option. */
const DEPLOY_BRANCH = 'main'

/** Defaults for the `deploy` block of `devkit.config.mjs`. */
export const DEPLOY_DEFAULTS = {
  /** The production database service in the compose file (CTR-4 role name). */
  databaseService: 'db',
  /** Production compose files (CONF-11); `compose.override.yml` is added when the server has one. */
  composeFiles: ['compose.server.yml'],
  /** Pre-deploy dumps kept on the server (CTR-12). */
  backupsKept: 10,
  /** The tracked nginx site file and its installed name; null for a product with no site. */
  site: { source: 'nginx.server.conf', name: null },
  /** How long every service may take to report healthy. */
  healthWaitSeconds: 300,
  /** Update submodules after the pull, when the repo has any; a build may import them. */
  submodules: true,
  /** The package.json whose `version` labels the image; a workspace's when the product version lives there. */
  versionFrom: 'package.json',
}

/** How each database engine is dumped inside its container, and the line a complete dump ends with. */
const DUMPS = {
  postgres: {
    command: 'exec pg_dump -U "$POSTGRES_USER" "$POSTGRES_DB"',
    trailer: 'PostgreSQL database dump complete',
  },
  mariadb: {
    command:
      'MYSQL_PWD="$MARIADB_PASSWORD" exec mariadb-dump -u"$MARIADB_USER" "$MARIADB_DATABASE"',
    trailer: '-- Dump completed',
  },
}

/** Quotes one value for bash. */
export function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`
}

/**
 * Reads the command-line options and the target from the environment.
 * @param {string[]} argv Arguments after the script name.
 * @param {Record<string, string | undefined>} env Usually `process.env`.
 */
export function parseOptions(argv, env) {
  const known = [
    '--skip-validate',
    '--skip-backup',
    '--no-prune',
    '--dry-run',
    '--help',
  ]
  const unknown = argv.filter((argument) => !known.includes(argument))
  if (unknown.length > 0) throw new Error(`Unknown argument: ${unknown[0]}`)

  return {
    help: argv.includes('--help'),
    dryRun: argv.includes('--dry-run'),
    skipValidate: argv.includes('--skip-validate'),
    skipBackup: argv.includes('--skip-backup') || env.DEPLOY_BACKUP === '0',
    skipPrune: argv.includes('--no-prune') || env.DEPLOY_PRUNE === '0',
    host: env.DEPLOY_SSH_HOST?.trim() ?? '',
    // Unset by default: a `-p` always wins over the port an ssh config alias sets.
    port: env.DEPLOY_SSH_PORT?.trim() ?? '',
    repoPath: env.DEPLOY_REPO_PATH?.trim() ?? '',
    backupDir: env.DEPLOY_BACKUP_DIR?.trim() || '.backups',
    // No default: it is a server path, which belongs in the untracked .env, never in a repo.
    sitesDir: env.DEPLOY_NGINX_SITES_DIR?.trim() ?? '',
    nginxContainer: env.DEPLOY_NGINX_CONTAINER?.trim() || 'nginx',
  }
}

/**
 * Requires the nginx sites folder when this deploy installs a site file, before anything reaches
 * the server. It must be an absolute server path; a product with `deploy.site: null` needs none.
 * @param {{ sitesDir: string }} options From `parseOptions`.
 * @param {{ site: object | null }} settings From `deploySettings`.
 */
export function requireSitesDir(options, settings) {
  if (!settings.site) return
  if (!options.sitesDir) {
    throw new Error(
      'Set DEPLOY_NGINX_SITES_DIR to the nginx sites folder on the server, for example /srv/nginx/sites, or set deploy.site to null in devkit.config.mjs.',
    )
  }
  if (!options.sitesDir.startsWith('/')) {
    throw new Error(
      `DEPLOY_NGINX_SITES_DIR must be an absolute path on the server; it is ${options.sitesDir}`,
    )
  }
}

/**
 * Combines the app's `deploy` block and database engine with the defaults, and checks that a
 * configured site file exists, so a deploy cannot half-finish for want of it.
 * @param {string} repoRoot The app checkout.
 * @param {object} config The app's `devkit.config.mjs` default export, or `{}`.
 */
export function deploySettings(repoRoot, config) {
  const deploy = { ...DEPLOY_DEFAULTS, ...config.deploy }
  const pkg = JSON.parse(
    readFileSync(path.join(repoRoot, 'package.json'), 'utf8'),
  )
  const versionFile = path.join(repoRoot, deploy.versionFrom)
  if (!existsSync(versionFile)) {
    throw new Error(
      `deploy.versionFrom names ${deploy.versionFrom}, which does not exist`,
    )
  }
  const version = String(
    JSON.parse(readFileSync(versionFile, 'utf8')).version ?? '',
  )
  if (!version) {
    throw new Error(
      `Set "version" in ${deploy.versionFrom}; it labels the deployed image`,
    )
  }
  const engine = config.database?.engine ?? 'postgres'
  if (!DUMPS[engine]) throw new Error(`Unsupported database engine: ${engine}`)

  let site = null
  if (deploy.site !== null) {
    site = { ...DEPLOY_DEFAULTS.site, ...deploy.site }
    if (!site.name) {
      const product = String(pkg.name ?? '').replace(/^@[^/]+\//, '')
      if (!product) throw new Error('Set deploy.site.name in devkit.config.mjs')
      site.name = `${product}.conf`
    }
    if (!existsSync(path.join(repoRoot, site.source))) {
      throw new Error(
        `The site file ${site.source} does not exist. Track it, or set deploy.site to null in devkit.config.mjs.`,
      )
    }
  }

  return { ...deploy, site, version, dump: DUMPS[engine] }
}

/** Lines that select the compose files, adding the server's own override when it has one. */
function composeLines(settings) {
  return [
    'compose_args=()',
    ...settings.composeFiles.map(
      (file) => `compose_args+=("-f" ${shellQuote(file)})`,
    ),
    'if [[ -f compose.override.yml ]]; then compose_args+=("-f" "compose.override.yml"); fi',
  ]
}

/**
 * Lines that find this checkout's running database container without the compose files, so the
 * lookup works on the deploy that first switches to a renamed file, before the pull brings it.
 *
 * Compose labels every container with its project folder (the folder of the first compose file)
 * and its service name; those two identify this checkout's database however the project is named,
 * and before and after `name:` changes. The checkout and each configured compose file's folder are
 * tried, with and without symlinks resolved. A docker error is fatal, never "nothing to back up"; only no matching container
 * means a first deploy, and more than one is refused as ambiguous.
 */
function findDatabaseLines(service, composeFiles) {
  const composeDirs = [
    ...new Set(composeFiles.map((file) => path.posix.dirname(file))),
  ].filter((dir) => dir !== '.')
  return [
    'checkout_dirs=("$PWD" "$(pwd -P)")',
    ...composeDirs.map(
      (dir) =>
        `checkout_dirs+=("$PWD/"${shellQuote(dir)} "$(pwd -P)/"${shellQuote(dir)})`,
    ),
    'db_ids=""',
    'for checkout_dir in "${checkout_dirs[@]}"; do',
    '  if ! found="$(docker ps -q \\',
    `      --filter "label=com.docker.compose.service=${service}" \\`,
    '      --filter "label=com.docker.compose.project.working_dir=$checkout_dir")"; then',
    '    echo "Could not list containers to find the database; refusing to deploy without a backup." >&2',
    '    exit 1',
    '  fi',
    '  db_ids+="$found"$\'\\n\'',
    'done',
    'db_container="$(printf "%s" "$db_ids" | sed "/^$/d" | sort -u)"',
    'if [[ "$(printf "%s" "$db_container" | grep -c .)" -gt 1 ]]; then',
    `  echo "More than one running ${service} container belongs to this checkout; refusing to guess which to back up." >&2`,
    '  exit 1',
    'fi',
  ]
}

/**
 * Lines that dump the database before the checkout or containers change. pg_dump and
 * mariadb-dump can exit 0 after a dropped connection, so the dump must pass `gzip -t` and end with
 * the engine's completion trailer; an incomplete dump is deleted and the deploy stops.
 *
 * Dumps hold every user's data, so they are written in a subshell with `umask 077`: the folder
 * is 700 and each dump 600, while the rest of the deploy keeps the checkout's normal modes.
 */
function backupLines(settings, options, sha) {
  if (options.skipBackup) {
    return ['echo "Skipping the database backup (--skip-backup)."']
  }
  const dir = shellQuote(options.backupDir)
  const service = settings.databaseService
  return [
    'echo "Backing up the database before deploying..."',
    ...findDatabaseLines(service, settings.composeFiles),
    'if [[ -z "$db_container" ]]; then',
    `  echo "No running ${service} container belongs to this checkout yet: nothing to back up."`,
    'else',
    '  (',
    '    umask 077',
    `    mkdir -p ${dir}`,
    `    chmod 700 ${dir}`,
    `    backup_file=${dir}/"pre-deploy-$(date -u +%Y%m%dT%H%M%SZ)-${sha.slice(0, 12)}.sql.gz"`,
    '    dump_ok=1',
    `    docker exec -i "$db_container" sh -c ${shellQuote(settings.dump.command)} | gzip > "$backup_file" || dump_ok=0`,
    `    if [[ $dump_ok -eq 0 ]] || ! gzip -t "$backup_file" || ! gzip -dc "$backup_file" | tail -5 | grep -qF ${shellQuote(settings.dump.trailer)}; then`,
    '      rm -f "$backup_file"',
    '      echo "The database dump is incomplete; refusing to deploy. Rerun with --skip-backup only once a dump exists another way." >&2',
    '      exit 1',
    '    fi',
    '    echo "Database backed up to $backup_file ($(du -h "$backup_file" | cut -f1))"',
    `    ls -1t ${dir}/pre-deploy-*.sql.gz 2>/dev/null | tail -n +${settings.backupsKept + 1} | xargs -r rm -f`,
    '  )',
    'fi',
  ]
}

/**
 * Lines that fast-forward the checkout, stop unless it landed on the commit validated locally,
 * and bring submodules to the pinned commits, since a production build may import one and a
 * fresh checkout has none.
 */
function updateLines(settings, sha) {
  return [
    `git fetch origin ${DEPLOY_BRANCH}`,
    `git checkout ${DEPLOY_BRANCH}`,
    `git pull --ff-only origin ${DEPLOY_BRANCH}`,
    `if [[ "$(git rev-parse HEAD)" != ${shellQuote(sha)} ]]; then`,
    `  echo "Refusing to continue: the server checkout is not at ${sha.slice(0, 12)}, the commit validated locally. Did someone push meanwhile?" >&2`,
    '  exit 1',
    'fi',
    ...(settings.submodules
      ? [
          'if [[ -f .gitmodules ]]; then',
          '  git submodule sync --recursive',
          '  git submodule update --init --recursive',
          'fi',
        ]
      : []),
  ]
}

/**
 * Lines that start the stack and wait for every service to be healthy, or stop with the logs.
 * DEPLOY_REVISION (the validated commit) and DEPLOY_VERSION (package.json) are exported first, so
 * `compose.server.yml` can pass them as build args for the image's OCI labels (CTR-1).
 */
function startLines(settings, sha) {
  const wait = settings.healthWaitSeconds
  return [
    `export DEPLOY_REVISION=${shellQuote(sha)}`,
    `export DEPLOY_VERSION=${shellQuote(settings.version)}`,
    `if ! docker compose "\${compose_args[@]}" up --build -d --wait --wait-timeout ${wait}; then`,
    `  echo "A service did not become healthy within ${wait} seconds; the deploy stopped. Status and recent logs:" >&2`,
    '  docker compose "${compose_args[@]}" ps >&2 || true',
    '  docker compose "${compose_args[@]}" logs --tail=100 >&2 || true',
    '  exit 1',
    'fi',
    'docker compose "${compose_args[@]}" ps',
  ]
}

/**
 * Lines that install the site file when it changed (CTR-8): the previous file is kept outside
 * `conf.d`, the new one must pass `nginx -t`, and nginx reloads gracefully. A failed test restores
 * the previous file (or removes a first install) and fails the deploy.
 */
function siteLines(settings, options) {
  if (!settings.site) return []
  const source = shellQuote(settings.site.source)
  const sitesDir = shellQuote(options.sitesDir)
  const name = shellQuote(settings.site.name)
  const nginx = shellQuote(options.nginxContainer)
  return [
    `site_dest=${sitesDir}/${name}`,
    `if [[ -f "$site_dest" ]] && cmp -s ${source} "$site_dest"; then`,
    '  echo "The nginx site file is unchanged."',
    'else',
    `  site_backups="$(dirname ${sitesDir})/site-backups"`,
    '  previous_site=""',
    '  if [[ -f "$site_dest" ]]; then',
    '    mkdir -p "$site_backups"',
    `    previous_site="$site_backups/"${name}".$(date -u +%Y%m%dT%H%M%SZ)"`,
    '    cp -p "$site_dest" "$previous_site"',
    '  fi',
    `  cp ${source} "$site_dest"`,
    `  if docker exec ${nginx} nginx -t; then`,
    `    docker exec ${nginx} nginx -s reload`,
    '    echo "Installed and reloaded the nginx site file."',
    '  else',
    '    if [[ -n "$previous_site" ]]; then cp -p "$previous_site" "$site_dest"; else rm -f "$site_dest"; fi',
    '    echo "The new nginx site file failed nginx -t; the previous one is back in place. The app containers are already updated." >&2',
    '    exit 1',
    '  fi',
    'fi',
  ]
}

/**
 * Builds the bash script run on the server, in CTR-11's order.
 * @param {object} settings From `deploySettings`.
 * @param {object} options From `parseOptions`.
 * @param {string} sha The full commit validated locally.
 */
export function buildRemoteScript(settings, options, sha) {
  return [
    'set -euo pipefail',
    `cd ${shellQuote(options.repoPath)}`,
    ...composeLines(settings),
    'if [[ -n "$(git status --short --untracked-files=no)" ]]; then',
    '  echo "Refusing to deploy: the server checkout has tracked changes." >&2',
    '  git status --short --untracked-files=no >&2',
    '  exit 1',
    'fi',
    ...backupLines(settings, options, sha),
    ...updateLines(settings, sha),
    ...startLines(settings, sha),
    ...siteLines(settings, options),
    ...(options.skipPrune
      ? []
      : ['echo "Pruning dangling images..."', 'docker image prune -f || true']),
    'echo "Deployed commit $(git rev-parse --short HEAD)."',
  ].join('\n')
}

/**
 * The ssh arguments for the deploy. `-p` is passed only when DEPLOY_SSH_PORT is set, so a host
 * alias's own `Port` in the ssh config is used otherwise.
 */
export function sshArguments(options, script) {
  return [
    ...(options.port ? ['-p', options.port] : []),
    options.host,
    `bash -lc ${shellQuote(script)}`,
  ]
}

/** Runs a local command, returning trimmed stdout; exits with its status when it fails. */
function run(command, args, { cwd, capture = false }) {
  const result = spawnSync(command, args, {
    cwd,
    encoding: 'utf8',
    stdio: capture ? ['inherit', 'pipe', 'inherit'] : 'inherit',
  })
  if (result.error) throw result.error
  if (result.status !== 0) process.exit(result.status ?? 1)
  return result.stdout?.trim() ?? ''
}

/** Refuses anything but a clean tree whose HEAD is a freshly fetched origin/main; returns the SHA. */
function requireCleanPushedMain(repoRoot) {
  if (run('git', ['status', '--porcelain'], { cwd: repoRoot, capture: true })) {
    throw new Error(
      'Refusing to deploy: the local tree has uncommitted changes.',
    )
  }
  run('git', ['fetch', 'origin', DEPLOY_BRANCH], { cwd: repoRoot })
  const head = run('git', ['rev-parse', 'HEAD'], {
    cwd: repoRoot,
    capture: true,
  })
  const remote = run('git', ['rev-parse', `origin/${DEPLOY_BRANCH}`], {
    cwd: repoRoot,
    capture: true,
  })
  if (head !== remote) {
    throw new Error(
      `Refusing to deploy: HEAD (${head.slice(0, 8)}) is not origin/${DEPLOY_BRANCH} (${remote.slice(0, 8)}). Push to ${DEPLOY_BRANCH} first.`,
    )
  }
  return head
}

async function main() {
  const repoRoot = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '../..',
  )
  const options = parseOptions(process.argv.slice(2), process.env)
  if (options.help) {
    console.log(
      readFileSync(fileURLToPath(import.meta.url), 'utf8').split('*/')[0],
    )
    return
  }
  if (!options.host)
    throw new Error('Set DEPLOY_SSH_HOST to the SSH host to deploy to.')
  if (!options.repoPath)
    throw new Error('Set DEPLOY_REPO_PATH to the checkout path on the server.')

  const configPath = path.join(repoRoot, 'devkit.config.mjs')
  const config = existsSync(configPath)
    ? (await import(pathToFileURL(configPath).href)).default
    : {}
  const settings = deploySettings(repoRoot, config)
  requireSitesDir(options, settings)
  const sha = requireCleanPushedMain(repoRoot)
  const script = buildRemoteScript(settings, options, sha)
  const sshArgs = sshArguments(options, script)

  if (options.dryRun) {
    console.log(
      `Would deploy ${sha.slice(0, 12)} to ${options.host}:${options.repoPath}`,
    )
    console.log(`Validate first: ${options.skipValidate ? 'no' : 'yes'}`)
    console.log('Server script:\n')
    console.log(script)
    return
  }

  if (!options.skipValidate) run('npm', ['run', 'validate'], { cwd: repoRoot })
  run('ssh', sshArgs, { cwd: repoRoot })
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  try {
    await main()
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error))
    process.exit(1)
  }
}
